#include <jni.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

/* Circuit breaker states */
#define CB_CLOSED 0
#define CB_OPEN 1
#define CB_HALF_OPEN 2

/* PDF generation error codes */
#define PDF_OK 0
#define PDF_ERR_MEMORY -1
#define PDF_ERR_IO -2
#define PDF_ERR_CIRCUIT_OPEN -3

typedef struct {
    int state;
    int failure_count;
    int failure_threshold;
    time_t last_failure_time;
    int recovery_timeout_sec;
    pthread_mutex_t lock;
} circuit_breaker_t;

typedef struct {
    char *buffer;
    size_t capacity;
    size_t length;
    int page_count;
    circuit_breaker_t *cb;
} pdf_context_t;

static circuit_breaker_t g_circuit_breaker = {
    .state = CB_CLOSED,
    .failure_count = 0,
    .failure_threshold = 5,
    .last_failure_time = 0,
    .recovery_timeout_sec = 30,
    .lock = PTHREAD_MUTEX_INITIALIZER
};

static int cb_allow_request(circuit_breaker_t *cb) {
    pthread_mutex_lock(&cb->lock);
    if (cb->state == CB_CLOSED) {
        pthread_mutex_unlock(&cb->lock);
        return 1;
    }
    if (cb->state == CB_OPEN) {
        time_t now = time(NULL);
        if (difftime(now, cb->last_failure_time) >= cb->recovery_timeout_sec) {
            cb->state = CB_HALF_OPEN;
            pthread_mutex_unlock(&cb->lock);
            return 1;
        }
        pthread_mutex_unlock(&cb->lock);
        return 0;
    }
    /* HALF_OPEN: allow one request */
    pthread_mutex_unlock(&cb->lock);
    return 1;
}

static void cb_record_success(circuit_breaker_t *cb) {
    pthread_mutex_lock(&cb->lock);
    cb->failure_count = 0;
    cb->state = CB_CLOSED;
    pthread_mutex_unlock(&cb->lock);
}

static void cb_record_failure(circuit_breaker_t *cb) {
    pthread_mutex_lock(&cb->lock);
    cb->failure_count++;
    cb->last_failure_time = time(NULL);
    if (cb->failure_count >= cb->failure_threshold) {
        cb->state = CB_OPEN;
    }
    pthread_mutex_unlock(&cb->lock);
}

static pdf_context_t* pdf_create_context(size_t initial_capacity) {
    pdf_context_t *ctx = (pdf_context_t*)malloc(sizeof(pdf_context_t));
    if (!ctx) return NULL;
    ctx->buffer = (char*)malloc(initial_capacity);
    if (!ctx->buffer) {
        free(ctx);
        return NULL;
    }
    ctx->capacity = initial_capacity;
    ctx->length = 0;
    ctx->page_count = 0;
    ctx->cb = &g_circuit_breaker;
    return ctx;
}

static int pdf_append_content(pdf_context_t *ctx, const char *content, size_t content_len) {
    if (ctx->length + content_len > ctx->capacity) {
        size_t new_cap = ctx->capacity * 2;
        while (new_cap < ctx->length + content_len) new_cap *= 2;
        char *new_buf = (char*)realloc(ctx->buffer, new_cap);
        if (!new_buf) return PDF_ERR_MEMORY;
        ctx->buffer = new_buf;
        ctx->capacity = new_cap;
    }
    memcpy(ctx->buffer + ctx->length, content, content_len);
    ctx->length += content_len;
    return PDF_OK;
}

static void pdf_destroy_context(pdf_context_t *ctx) {
    if (ctx) {
        if (ctx->buffer) free(ctx->buffer);
        free(ctx);
    }
}

/*
 * JNI entry point: generates PDF from Java string content.
 * Uses circuit breaker to prevent cascading failures.
 * Returns byte array of PDF content or null on failure.
 */
JNIEXPORT jbyteArray JNICALL Java_com_docgen_PdfEngine_nativeGeneratePdf(
    JNIEnv *env, jobject this, jstring title, jstring body, jint max_pages) {

    if (!cb_allow_request(&g_circuit_breaker)) {
        jclass exc = (*env)->FindClass(env, "com/docgen/CircuitOpenException");
        if (exc) (*env)->ThrowNew(env, exc, "Circuit breaker is open");
        return NULL;
    }

    const char *title_chars = (*env)->GetStringUTFChars(env, title, NULL);
    if (!title_chars) {
        cb_record_failure(&g_circuit_breaker);
        return NULL;
    }

    const char *body_chars = (*env)->GetStringUTFChars(env, body, NULL);
    if (!body_chars) {
        (*env)->ReleaseStringUTFChars(env, title, title_chars);
        cb_record_failure(&g_circuit_breaker);
        return NULL;
    }

    jsize title_len = (*env)->GetStringUTFLength(env, title);
    jsize body_len = (*env)->GetStringUTFLength(env, body);

    /* Validate max_pages to prevent resource exhaustion */
    if (max_pages <= 0 || max_pages > 1000) {
        max_pages = 100;
    }

    pdf_context_t *ctx = pdf_create_context(4096);
    if (!ctx) {
        (*env)->ReleaseStringUTFChars(env, title, title_chars);
        (*env)->ReleaseStringUTFChars(env, body, body_chars);
        cb_record_failure(&g_circuit_breaker);
        return NULL;
    }

    /* Write PDF header */
    const char *header = "%PDF-1.4\n";
    pdf_append_content(ctx, header, strlen(header));

    /* Write title object */
    char obj_buf[512];
    int written = snprintf(obj_buf, sizeof(obj_buf),
        "1 0 obj\n<< /Title (%.*s) /Pages 2 0 R >>\nendobj\n",
        (int)title_len, title_chars);
    if (written > 0 && (size_t)written < sizeof(obj_buf)) {
        pdf_append_content(ctx, obj_buf, written);
    }

    /* Process body content - split into pages */
    size_t offset = 0;
    int page_num = 0;
    size_t chunk_size = 4000; /* bytes per page */

    while (offset < (size_t)body_len && page_num < max_pages) {
        size_t remaining = body_len - offset;
        size_t this_chunk = remaining < chunk_size ? remaining : chunk_size;

        written = snprintf(obj_buf, sizeof(obj_buf),
            "%d 0 obj\n<< /Type /Page /Contents (%.*s) >>\nendobj\n",
            page_num + 3, (int)this_chunk, body_chars + offset);

        if (written > 0 && (size_t)written < sizeof(obj_buf)) {
            pdf_append_content(ctx, obj_buf, written);
        }
        offset += this_chunk;
        page_num++;
    }
    ctx->page_count = page_num;

    /* Release JNI strings AFTER we're done using the native pointers */
    (*env)->ReleaseStringUTFChars(env, title, title_chars);
    (*env)->ReleaseStringUTFChars(env, body, body_chars);

    /* Write PDF trailer */
    const char *trailer = "%%EOF\n";
    pdf_append_content(ctx, trailer, strlen(trailer));

    /* Create Java byte array from generated PDF */
    jbyteArray result = (*env)->NewByteArray(env, (jsize)ctx->length);
    if (!result) {
        pdf_destroy_context(ctx);
        cb_record_failure(&g_circuit_breaker);
        return NULL;
    }

    (*env)->SetByteArrayRegion(env, result, 0, (jsize)ctx->length,
                               (const jbyte*)ctx->buffer);

    pdf_destroy_context(ctx);
    cb_record_success(&g_circuit_breaker);
    return result;
}

/*
 * JNI entry point: batch PDF generation with shared context.
 * Reuses internal buffer across multiple documents for performance.
 */
JNIEXPORT jobjectArray JNICALL Java_com_docgen_PdfEngine_nativeBatchGenerate(
    JNIEnv *env, jobject this, jobjectArray titles, jobjectArray bodies) {

    if (!cb_allow_request(&g_circuit_breaker)) {
        jclass exc = (*env)->FindClass(env, "com/docgen/CircuitOpenException");
        if (exc) (*env)->ThrowNew(env, exc, "Circuit breaker is open");
        return NULL;
    }

    jsize count = (*env)->GetArrayLength(env, titles);
    jsize body_count = (*env)->GetArrayLength(env, bodies);
    if (count != body_count || count <= 0) {
        cb_record_failure(&g_circuit_breaker);
        return NULL;
    }

    jclass byteArrayClass = (*env)->FindClass(env, "[B");
    jobjectArray results = (*env)->NewObjectArray(env, count, byteArrayClass, NULL);
    if (!results) {
        cb_record_failure(&g_circuit_breaker);
        return NULL;
    }

    /* Shared context for batch - reuse buffer across iterations */
    pdf_context_t *ctx = pdf_create_context(8192);
    if (!ctx) {
        cb_record_failure(&g_circuit_breaker);
        return NULL;
    }

    for (jsize i = 0; i < count; i++) {
        jstring jtitle = (jstring)(*env)->GetObjectArrayElement(env, titles, i);
        jstring jbody = (jstring)(*env)->GetObjectArrayElement(env, bodies, i);

        if (!jtitle || !jbody) continue;

        const char *t = (*env)->GetStringUTFChars(env, jtitle, NULL);
        const char *b = (*env)->GetStringUTFChars(env, jbody, NULL);
        if (!t || !b) {
            if (t) (*env)->ReleaseStringUTFChars(env, jtitle, t);
            if (b) (*env)->ReleaseStringUTFChars(env, jbody, b);
            continue;
        }

        jsize tlen = (*env)->GetStringUTFLength(env, jtitle);
        jsize blen = (*env)->GetStringUTFLength(env, jbody);

        /* Reset context for reuse - keep allocated buffer */
        ctx->length = 0;
        ctx->page_count = 0;

        const char *header = "%PDF-1.4\n";
        pdf_append_content(ctx, header, strlen(header));

        char obj_buf[512];
        int written = snprintf(obj_buf, sizeof(obj_buf),
            "1 0 obj\n<< /Title (%.*s) >>\nendobj\n", (int)tlen, t);
        if (written > 0 && (size_t)written < sizeof(obj_buf))
            pdf_append_content(ctx, obj_buf, written);

        written = snprintf(obj_buf, sizeof(obj_buf),
            "2 0 obj\n<< /Type /Page /Contents (%.*s) >>\nendobj\n",
            (int)blen, b);
        if (written > 0 && (size_t)written < sizeof(obj_buf))
            pdf_append_content(ctx, obj_buf, written);

        (*env)->ReleaseStringUTFChars(env, jtitle, t);
        (*env)->ReleaseStringUTFChars(env, jbody, b);

        const char *trailer = "%%EOF\n";
        pdf_append_content(ctx, trailer, strlen(trailer));

        jbyteArray pdf = (*env)->NewByteArray(env, (jsize)ctx->length);
        if (pdf) {
            (*env)->SetByteArrayRegion(env, pdf, 0, (jsize)ctx->length,
                                       (const jbyte*)ctx->buffer);
            (*env)->SetObjectArrayElement(env, results, i, pdf);
            (*env)->DeleteLocalRef(env, pdf);
        }
        (*env)->DeleteLocalRef(env, jtitle);
        (*env)->DeleteLocalRef(env, jbody);
    }

    pdf_destroy_context(ctx);
    cb_record_success(&g_circuit_breaker);
    return results;
}
